"use strict";
import { useQuery } from "@tanstack/react-query";
import { useAccount } from "hooks/useAccount";
import { useEthersProvider } from "hooks/useEthersProvider";
import NonfungiblePositionManagerJson from "@uniswap/v3-periphery/artifacts/contracts/NonfungiblePositionManager.sol/NonfungiblePositionManager.json";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import { getContract } from "utilities/src/contracts/getContract";
import { PositionStatus } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { CurrencyAmount, Token } from "@uniswap/sdk-core";
import { Pool as V3Pool, TickMath } from "@uniswap/v3-sdk";
import JSBI from "jsbi";
function getV3PositionStatus(currentTick, tickLower, tickUpper, hasLiquidity) {
  if (!hasLiquidity) {
    return PositionStatus.CLOSED;
  }
  if (currentTick >= tickLower && currentTick <= tickUpper) {
    return PositionStatus.IN_RANGE;
  } else {
    return PositionStatus.OUT_OF_RANGE;
  }
}
const { abi: NFTPositionManagerABI } = NonfungiblePositionManagerJson;
const V3_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/aborean-finance-v3-abstract-testnet/api";
const GET_POOL_QUERY = `
  query GetPool($token0: String!, $token1: String!) {
    pools(
      where: {
        or: [
          {
            and: [
              { token0: $token0 },
              { token1: $token1 }
            ]
          },
          {
            and: [
              { token0: $token1 },
              { token1: $token0 }
            ]
          }
        ]
      }
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      tickSpacing
      liquidity
      sqrtPrice
      tick
      totalValueLockedUSD
    }
  }
`;
async function fetchPoolData(token0, token1, tickSpacing) {
  try {
    const response = await fetch(V3_SUBGRAPH_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        query: GET_POOL_QUERY,
        variables: {
          token0: token0.toLowerCase(),
          token1: token1.toLowerCase()
        }
      })
    });
    const data = await response.json();
    if (data.errors) {
      console.error("Pool query errors:", data.errors);
      return null;
    }
    const pools = data.data?.pools || [];
    const matchingPool = pools.find(
      (pool) => parseInt(pool.tickSpacing) === tickSpacing
    );
    if (matchingPool) {
      return matchingPool;
    } else {
      return null;
    }
  } catch (error) {
    console.error("Failed to fetch pool data:", error);
    return null;
  }
}
export function useAbstractPosition(tokenId, chainId) {
  const account = useAccount();
  const provider = useEthersProvider({ chainId });
  const contracts = getAbstractContracts(chainId);
  return useQuery({
    queryKey: ["abstract-position", tokenId, chainId, account.address],
    queryFn: async () => {
      if (!tokenId || !account.address || !provider || !contracts?.nonfungiblePositionManager) {
        return null;
      }
      try {
        const positionManager = getContract(
          contracts.nonfungiblePositionManager,
          NFTPositionManagerABI,
          provider
        );
        if (!positionManager) return null;
        let owner;
        try {
          owner = await positionManager.ownerOf(tokenId);
        } catch (error) {
          console.error("Position does not exist:", error);
          return null;
        }
        if (owner.toLowerCase() !== account.address.toLowerCase()) {
          console.error("Position not owned by current account");
          return null;
        }
        const positionData = await positionManager.positions(tokenId);
        const positionTickSpacing = positionData[4];
        const poolData = await fetchPoolData(positionData[2], positionData[3], positionTickSpacing);
        const positionInfo = {
          tokenId,
          owner,
          token0: positionData[2],
          token1: positionData[3],
          tickLower: positionData[5],
          tickUpper: positionData[6],
          liquidity: positionData[7].toString(),
          feeGrowthInside0LastX128: positionData[8].toString(),
          feeGrowthInside1LastX128: positionData[9].toString(),
          tokensOwed0: positionData[10].toString(),
          tokensOwed1: positionData[11].toString(),
          poolData
        };
        let currency0Amount, currency1Amount, position, pool;
        if (poolData) {
          try {
            const token0 = new Token(
              chainId,
              positionData[2],
              // token0 address
              parseInt(poolData.token0.decimals),
              poolData.token0.symbol,
              poolData.token0.name
            );
            const token1 = new Token(
              chainId,
              positionData[3],
              // token1 address
              parseInt(poolData.token1.decimals),
              poolData.token1.symbol,
              poolData.token1.name
            );
            const feeAmount = parseInt(poolData.tickSpacing) === 1 ? 100 : parseInt(poolData.tickSpacing) === 50 ? 500 : parseInt(poolData.tickSpacing) === 100 ? 500 : parseInt(poolData.tickSpacing) === 200 ? 3e3 : parseInt(poolData.tickSpacing) === 2e3 ? 1e4 : 3e3;
            pool = new V3Pool(
              token0,
              token1,
              feeAmount,
              JSBI.BigInt(poolData.sqrtPrice),
              JSBI.BigInt(poolData.liquidity),
              parseInt(poolData.tick)
            );
            if (positionData[5] >= positionData[6]) {
              throw new Error(`Invalid tick range: tickLower (${positionData[5]}) must be less than tickUpper (${positionData[6]})`);
            }
            const MIN_TICK = TickMath.MIN_TICK;
            const MAX_TICK = TickMath.MAX_TICK;
            const tickSpacing = parseInt(poolData.tickSpacing);
            const minValidTick = Math.ceil(MIN_TICK / tickSpacing) * tickSpacing;
            const maxValidTick = Math.floor(MAX_TICK / tickSpacing) * tickSpacing;
            const positionLiquidity = JSBI.BigInt(positionData[7].toString());
            if (JSBI.equal(positionLiquidity, JSBI.BigInt(0))) {
              currency0Amount = CurrencyAmount.fromRawAmount(token0, 0);
              currency1Amount = CurrencyAmount.fromRawAmount(token1, 0);
            } else {
              try {
                const decreaseParams = {
                  tokenId,
                  liquidity: positionData[7],
                  // liquidity
                  amount0Min: 0,
                  amount1Min: 0,
                  deadline: Math.floor(Date.now() / 1e3) + 3600
                };
                const result = await positionManager.callStatic.decreaseLiquidity(decreaseParams);
                currency0Amount = CurrencyAmount.fromRawAmount(token0, result.amount0.toString());
                currency1Amount = CurrencyAmount.fromRawAmount(token1, result.amount1.toString());
              } catch (simulationError) {
                const currentTick = parseInt(poolData.tick);
                const inRange = currentTick >= positionData[5] && currentTick <= positionData[6];
                if (inRange) {
                  const amount0Estimate = JSBI.divide(positionLiquidity, JSBI.BigInt(1e6));
                  const amount1Estimate = JSBI.divide(positionLiquidity, JSBI.BigInt(1e6));
                  currency0Amount = CurrencyAmount.fromRawAmount(token0, amount0Estimate.toString());
                  currency1Amount = CurrencyAmount.fromRawAmount(token1, amount1Estimate.toString());
                } else if (currentTick < positionData[5]) {
                  const amount0Estimate = JSBI.divide(positionLiquidity, JSBI.BigInt(1e5));
                  currency0Amount = CurrencyAmount.fromRawAmount(token0, amount0Estimate.toString());
                  currency1Amount = CurrencyAmount.fromRawAmount(token1, 0);
                } else {
                  const amount1Estimate = JSBI.divide(positionLiquidity, JSBI.BigInt(1e5));
                  currency0Amount = CurrencyAmount.fromRawAmount(token0, 0);
                  currency1Amount = CurrencyAmount.fromRawAmount(token1, amount1Estimate.toString());
                }
              }
            }
          } catch (error) {
            console.error("Error calculating position amounts:", error);
            const token0 = new Token(
              chainId,
              positionData[2],
              // token0 address
              parseInt(poolData?.token0.decimals || "18"),
              poolData?.token0.symbol || "TOKEN0",
              poolData?.token0.name || "Token 0"
            );
            const token1 = new Token(
              chainId,
              positionData[3],
              // token1 address
              parseInt(poolData?.token1.decimals || "18"),
              poolData?.token1.symbol || "TOKEN1",
              poolData?.token1.name || "Token 1"
            );
            currency0Amount = CurrencyAmount.fromRawAmount(token0, 0);
            currency1Amount = CurrencyAmount.fromRawAmount(token1, 0);
          }
        } else {
          const token0 = new Token(
            chainId,
            positionData[2],
            // token0 address
            18,
            "TOKEN0",
            "Token 0"
          );
          const token1 = new Token(
            chainId,
            positionData[3],
            // token1 address
            18,
            "TOKEN1",
            "Token 1"
          );
          currency0Amount = CurrencyAmount.fromRawAmount(token0, 0);
          currency1Amount = CurrencyAmount.fromRawAmount(token1, 0);
        }
        let token0UncollectedFees = "0";
        let token1UncollectedFees = "0";
        if (pool && position) {
          try {
            const collectParams = {
              tokenId,
              recipient: account.address,
              amount0Max: "0",
              amount1Max: "0"
            };
            token0UncollectedFees = positionData[10].toString();
            token1UncollectedFees = positionData[11].toString();
          } catch (error) {
            console.error("Error fetching uncollected fees:", error);
          }
        }
        return {
          position: {
            position: {
              case: "v3Position",
              value: {
                tokenId,
                token0: {
                  address: positionData[2],
                  // token0 address
                  chainId,
                  decimals: parseInt(poolData?.token0.decimals || "18"),
                  symbol: poolData?.token0.symbol || "TOKEN0",
                  name: poolData?.token0.name || "Token 0"
                },
                token1: {
                  address: positionData[3],
                  // token1 address
                  chainId,
                  decimals: parseInt(poolData?.token1.decimals || "18"),
                  symbol: poolData?.token1.symbol || "TOKEN1",
                  name: poolData?.token1.name || "Token 1"
                },
                feeTier: poolData ? parseInt(poolData.tickSpacing) === 1 ? "100" : parseInt(poolData.tickSpacing) === 50 ? "500" : parseInt(poolData.tickSpacing) === 100 ? "500" : parseInt(poolData.tickSpacing) === 200 ? "3000" : parseInt(poolData.tickSpacing) === 2e3 ? "10000" : "3000" : "3000",
                // Add pool data that parseRestPosition needs
                poolId: poolData?.id || "",
                tickSpacing: positionTickSpacing.toString(),
                pool: poolData ? {
                  fee: parseInt(poolData.tickSpacing) === 1 ? 100 : parseInt(poolData.tickSpacing) === 50 ? 500 : parseInt(poolData.tickSpacing) === 100 ? 500 : parseInt(poolData.tickSpacing) === 200 ? 3e3 : parseInt(poolData.tickSpacing) === 2e3 ? 1e4 : 3e3,
                  sqrtPriceX96: poolData.sqrtPrice,
                  liquidity: poolData.liquidity,
                  tick: parseInt(poolData.tick),
                  tickSpacing: parseInt(poolData.tickSpacing),
                  // Add token prices that the rate display needs
                  token0Price: pool?.token0Price,
                  token1Price: pool?.token1Price
                } : void 0,
                liquidity: positionData[7].toString(),
                // liquidity
                tickLower: positionData[5].toString(),
                // tickLower
                tickUpper: positionData[6].toString(),
                // tickUpper
                amount0: currency0Amount?.quotient.toString() || "0",
                amount1: currency1Amount?.quotient.toString() || "0",
                token0UncollectedFees,
                token1UncollectedFees,
                apr: 0,
                // We don't calculate APR from on-chain data
                owner,
                poolId: poolData?.id || "",
                currentPrice: poolData?.sqrtPrice || "0",
                currentLiquidity: poolData?.liquidity || "0",
                currentTick: poolData?.tick || "0",
                tickSpacing: poolData?.tickSpacing || "200"
              }
            }
          },
          status: getV3PositionStatus(
            parseInt(poolData?.tick || "0"),
            positionData[5],
            // tickLower
            positionData[6],
            // tickUpper
            !positionData[7].eq(0)
            // hasLiquidity
          ),
          chainId,
          isHidden: false
        };
      } catch (error) {
        console.error("Error fetching position:", error);
        return null;
      }
    },
    enabled: !!tokenId && !!account.address && !!provider && !!contracts?.nonfungiblePositionManager,
    refetchInterval: 3e4
    // Refetch every 30 seconds
  });
}
